/// <summary>
/// This flight allows <c>WHSWorkExecuteDisplayCluster</c> to populate the product confirmation fields, with the value stored in the pass,
/// on cluster picking, but not on cluster putaway.
/// </summary>
internal final class WhsWorkExecuteDisplayClusterAllowPopulateProductConfirmationFlight extends Flight
{
    static private WhsWorkExecuteDisplayClusterAllowPopulateProductConfirmationFlight singleton = new WhsWorkExecuteDisplayClusterAllowPopulateProductConfirmationFlight();

}
